// Lê as O.S. de documentação das 5 bases e lista as pendentes (status A, sem técnico).
const BASES = ['RESOLUTTO', '4B', 'PONTO', 'CACTA', 'BUZZ'];
function parseTolerante(v) {
  if (v && typeof v === 'object' && v.data === undefined) return v;
  const txt = v && typeof v === 'object' ? v.data : v;
  const limpo = String(txt || '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
  try { return JSON.parse(limpo); } catch (e) { return { erro: 'JSON inválido: ' + e.message }; }
}
const out = [];
for (const b of BASES) {
  const r = parseTolerante($('OS ' + b).first().json);
  for (const os of (r.registros || [])) {
    const tec = String(os.id_tecnico || '0');
    if (os.status === 'A' && (tec === '0' || tec === '')) {
      out.push({ json: { base: b, id_chamado: Number(os.id), id_cliente: Number(os.id_cliente || 0), setor: String(os.setor || '') } });
    }
  }
}
// Sempre sai pelo menos um item, para o panorama de carga ser calculado mesmo sem pendentes.
if (!out.length) out.push({ json: { base: '', id_chamado: 0, id_cliente: 0, setor: '', vazio: true } });
return out;

// ================== CONFIG ==================
// true = só mostra o que faria (não encaminha). Passe para false depois de conferir.
const SIMULAR = false;

// Mesma pessoa, id de colaborador de cada base.
const PESSOAS = {
  tec22: { nome: 'Técnico 22',  RESOLUTTO: 22, '4B': 22, PONTO: 22, CACTA: 22, BUZZ: 22 },
  //tec52:    { nome: 'Técnico 52',    RESOLUTTO: 52, '4B': 46, PONTO: 52, CACTA: 62, BUZZ: 58 },
 // tec51:   { nome: 'Técnico 51', RESOLUTTO: 51, '4B': 61, PONTO: 59, CACTA: 49, BUZZ: 60 },
  tec42:   { nome: 'Técnico 42',      RESOLUTTO: 42, '4B': 42, PONTO: 42, CACTA: 42, BUZZ: 42 },
  tec43:{ nome: 'Técnico 43',  RESOLUTTO: 43, '4B': 43, PONTO: 43, CACTA: 43, BUZZ: 43 },
};

// Condomínio -> id do técnico NAQUELA base (vai direto, se a pessoa não estiver de folga).
// Só vale para quem está em PESSOAS (equipe de documentação); outro id é ignorado.
const CONDOMINIOS = {
  RESOLUTTO: {},
  '4B':      { 276: 22, 243: 46 },
  PONTO:     { 110: 59, 104: 59 },
  CACTA:     {},
  BUZZ:      { 271: 43, 280: 42 },
};

// Folga: CHAVES de PESSOAS (tec22, tec52, tec51, tec42, tec43).
// FOLGA_HOJE vale até você limpar; FOLGA_DATAS por data (AAAA-MM-DD).
const FOLGA_HOJE = ['tec52','tec51'];
const FOLGA_DATAS = { /* '2026-09-29': ['tec51'] */ };

// ---- Balanceamento (igual à auditoria) ----
// Conta quantas O.S. de documentação cada pessoa RECEBEU (técnico atual da O.S.),
// abertas nos últimos JANELA_DIAS dias, em QUALQUER status (inclusive finalizadas).
// Quem recebeu menos leva a próxima; empate -> sorteio. Acumular O.S. em aberto não
// "trava" a pessoa: ela continua recebendo a parte dela.
const JANELA_DIAS = 30;
// Opcional: só conta O.S. abertas a partir desta data (AAAA-MM-DD). Vazio = só a janela.
// Útil no dia da virada para todos partirem do zero.
const CONTAR_DESDE = '';

// Status que contam como "em aberto" (só informativo no panorama, não decide nada).
const STATUS_ABERTO = ['A', 'DS', 'AN', 'EX', 'EN', 'AS', 'RAG', 'AG'];

// Condomínio -> id do SETOR daquela base (vai no encaminhamento junto com o técnico).
// Condomínio sem setor aqui: mantém o setor atual da O.S. (ou pula, se SETOR_OBRIGATORIO = true).
const SETOR = {
  RESOLUTTO: { /* 212: 99, ... */ },
  '4B':  { /*CITY CENTER*/244: 12, /*PALLADIUM CURITIBA*/199: 11, /*PATO BRANCO*/276: 16, /*CATUAI PALLADIUM*/201: 14,
           /*CIDADE DOS LAGOS*/275: 13, /*PETRÓPOLIS*/243: 17, /*VENTURA*/200: 18, /*PALLADIUM UMUARAMA*/202: 15 },
  PONTO: { /*PÁTIO CHAPECÓ*/84: 18, /*PORTO BELO OUTLET*/134: 19, /*I FASHION OUTLET TIJUCAS*/144: 23, /*PULSE OPEN MALL*/273: 36,
           /*ITAJAI*/104: 37, /*PASSO FUNDO*/159: 17, /*SHOPPING SINOP*/216: 25, /*RIVIEIRA BUSINESS*/110: 43 },
  CACTA: { /*PARK CITY SUMARE*/253: 13, /*PATTEO URUPEMA*/247: 12, /*MOGI MIRIM*/248: 10, /*CATUAI CASCAVEL*/260: 15,
           /*JOCKEY PLAZA*/263: 11, /*PONTAL SHOPPING*/206: 14 },
  BUZZ:  { /*PLAZA CAMPOS GERAIS*/280: 12, /*ESTAÇÃO*/269: 11, /*GRAVATAI*/271: 10 },
};
const SETOR_OBRIGATORIO = false;

// ============================================

const BASES = ['RESOLUTTO', '4B', 'PONTO', 'CACTA', 'BUZZ'];
const SAIDA = { RESOLUTTO: 0, '4B': 1, PONTO: 2, CACTA: 3, BUZZ: 4 }; // 5 = não encaminha

// Validação: nada roda com a tabela incompleta.
const faltando = [];
for (const [k, p] of Object.entries(PESSOAS)) for (const b of BASES) if (!p[b]) faltando.push(`${k}.${b}`);
if (faltando.length) throw new Error('PESSOAS incompleta (preencha ou remova a pessoa da base): ' + faltando.join(', '));

function parseTolerante(v) {
  if (v && typeof v === 'object' && v.data === undefined) return v;
  const txt = v && typeof v === 'object' ? v.data : v;
  const limpo = String(txt || '').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');
  try { return JSON.parse(limpo); } catch (e) { return { erro: 'JSON inválido: ' + e.message }; }
}

// id (por base) -> chave da pessoa
const quem = {};
for (const b of BASES) { quem[b] = {}; for (const [k, p] of Object.entries(PESSOAS)) quem[b][String(p[b])] = k; }

// Datas no fuso de São Paulo (strings 'AAAA-MM-DD HH:MM:SS', comparáveis como texto)
const agoraSP = new Date(Date.now() - 3 * 3600 * 1000);
const hoje = agoraSP.toISOString().slice(0, 10);
let desde = new Date(agoraSP.getTime() - JANELA_DIAS * 86400 * 1000).toISOString().slice(0, 19).replace('T', ' ');
if (CONTAR_DESDE && CONTAR_DESDE + ' 00:00:00' > desde) desde = CONTAR_DESDE + ' 00:00:00';

// Folga aceita chave ou nome completo (compatível com a config antiga).
const porNome = Object.fromEntries(Object.entries(PESSOAS).map(([k, p]) => [p.nome, k]));
const folga = new Set([...FOLGA_HOJE, ...(FOLGA_DATAS[hoje] || [])].map(x => PESSOAS[x] ? x : porNome[x]).filter(Boolean));
const folgaInvalida = [...FOLGA_HOJE, ...(FOLGA_DATAS[hoje] || [])].filter(x => !PESSOAS[x] && !porNome[x]);

// 1) Recebidas na janela (todas as bases somadas) + em aberto (informativo)
const recebidas = {}, recebidasBase = {}, abertas = {};
for (const k of Object.keys(PESSOAS)) { recebidas[k] = 0; abertas[k] = 0; recebidasBase[k] = Object.fromEntries(BASES.map(b => [b, 0])); }
const errosBase = [];
const avisos = [];
const leitura = {};
for (const b of BASES) {
  const r = parseTolerante($('OS ' + b).first().json);
  if (r.erro || r.error || r.type === 'error') { errosBase.push({ base: b, erro: r.erro || r.message || JSON.stringify(r.error) }); continue; }
  const regs = r.registros || [];
  let naJanela = 0, maisAntiga = null;
  for (const os of regs) {
    const dt = String(os.data_abertura || '');
    if (dt && dt.slice(0, 4) !== '0000' && (!maisAntiga || dt < maisAntiga)) maisAntiga = dt;
    const k = quem[b][String(os.id_tecnico)];
    if (!k) continue;
    if (STATUS_ABERTO.includes(os.status)) abertas[k]++;
    if (dt >= desde) { naJanela++; recebidas[k]++; recebidasBase[k][b]++; }
  }
  // A listagem vem da mais nova para a mais antiga (rp 10000). Se cortou antes de cobrir a janela, a conta fica curta.
  if (Number(r.total || 0) > regs.length && maisAntiga && maisAntiga >= desde) {
    avisos.push(`${b}: a leitura (${regs.length} de ${r.total}) não cobre os ${JANELA_DIAS} dias — aumente o rp do nó "OS ${b}".`);
  }
  leitura[b] = { total_api: r.total, registros: regs.length, na_janela_da_equipe: naJanela, mais_antiga_lida: maisAntiga };
}
// Regra do condomínio vale só para a equipe de documentação: id fora de PESSOAS é ignorado (cai no balanceamento).
for (const b of BASES) for (const [c, t] of Object.entries(CONDOMINIOS[b] || {}))
  if (!quem[b][String(t)]) avisos.push(`CONDOMINIOS ${b} ${c}: técnico ${t} não é da equipe de documentação — ignorado, vai pelo balanceamento.`);
// Se alguma base falhou, a contagem fica errada: não encaminha nada nesta rodada.
const travar = errosBase.length > 0;

// 2) Pendentes + condomínio do cliente (nós "Cliente <BASE>" pareados por índice)
const pend = $('Pendentes').all();
const cli = {}; for (const b of BASES) cli[b] = $('Cliente ' + b).all();
const saida = [];
const recebidasInicio = JSON.parse(JSON.stringify(recebidas));
const daRodada = Object.fromEntries(Object.keys(PESSOAS).map(k => [k, 0]));

pend.forEach((it, i) => {
  const p = it.json;
  if (p.vazio) return;
  const b = p.base;
  const rc = parseTolerante(cli[b][i] ? cli[b][i].json : null);
  const cliente = (rc.registros || [])[0] || {};
  const cond = Number(cliente.id_condominio || 0);
  const setorCfg = (SETOR[b] || {})[cond];
  if (!setorCfg && SETOR_OBRIGATORIO) { saida.push({ json: { tipo: 'decisao', base: b, id_chamado: p.id_chamado, condominio: cond || null, regra: 'condomínio sem setor no SETOR — não mexe', saida: 5 } }); return; }
  const idSetor = String(setorCfg || p.setor);

  const candidatos = Object.keys(PESSOAS).filter(k => !folga.has(k));
  let escolhido = null, regra = '', sorteio = [];
  const tecCond = (CONDOMINIOS[b] || {})[cond];
  const kCond = tecCond ? quem[b][String(tecCond)] : null;
  if (kCond && !folga.has(kCond)) { escolhido = kCond; regra = `condominio ${cond} (direto)`; }
  else if (candidatos.length) {
    const min = Math.min(...candidatos.map(k => recebidas[k]));
    sorteio = candidatos.filter(k => recebidas[k] === min);
    escolhido = sorteio[Math.floor(Math.random() * sorteio.length)];
    regra = (kCond ? `condominio ${cond} (técnico de folga) → ` : '') + `menos recebidas em ${JANELA_DIAS} dias` + (sorteio.length > 1 ? ' (sorteio)' : '');
  }
  const antes = escolhido ? recebidas[escolhido] : null;
  // Condomínio também conta como recebida: quem pega condomínio recebe menos do "monte".
  if (escolhido) { recebidas[escolhido]++; recebidasBase[escolhido][b]++; daRodada[escolhido]++; }

  const idTec = escolhido ? PESSOAS[escolhido][b] : null;
  const enviar = !!escolhido && !SIMULAR && !travar;
  saida.push({ json: {
    tipo: 'decisao', base: b, id_chamado: p.id_chamado, id_cliente: p.id_cliente, condominio: cond || null,
    para: escolhido ? PESSOAS[escolhido].nome : '(ninguém disponível)', id_tecnico: idTec,
    id_setor: Number(idSetor), setor_origem: setorCfg ? 'SETOR do condomínio' : 'mantido da O.S.',
    regra, recebidas_antes: antes, sorteado_entre: sorteio.map(k => PESSOAS[k].nome),
    modo: SIMULAR ? 'SIMULAÇÃO' : (travar ? 'TRAVADO (erro em base)' : 'ENCAMINHAR'),
    saida: enviar ? SAIDA[b] : 5,
    payload: {
      id_chamado: String(p.id_chamado), alterar_setor: 'S', id_setor: idSetor, id_tecnico: String(idTec),
      status: 'EN', mensagem: `Encaminhado automaticamente (documentação, distribuição por recebidas em ${JANELA_DIAS} dias) para ${escolhido ? PESSOAS[escolhido].nome : ''}.`,
      id_assunto: '', data: '', id_evento: '', latitude: '', longitude: '', gps_time: '', historico: '',
    },
  } });
});

// 3) Panorama geral (sempre vai para a saída 5)
const panorama = Object.keys(PESSOAS).map(k => ({
  pessoa: PESSOAS[k].nome, folga: folga.has(k),
  recebidas_janela_antes: recebidasInicio[k], nesta_rodada: daRodada[k], recebidas_janela_depois: recebidas[k],
  em_aberto_agora: abertas[k], recebidas_por_base: recebidasBase[k],
}));
return [
  { json: { tipo: 'panorama', saida: 5, data: hoje, janela: `${JANELA_DIAS} dias (desde ${desde})`,
            modo: SIMULAR ? 'SIMULAÇÃO' : (travar ? 'TRAVADO' : 'ENCAMINHAR'),
            pendentes: saida.length, erros_base: errosBase, avisos, folga_invalida: folgaInvalida, panorama, leitura } },
  ...saida,
];

// Roda uma vez por O.S. encaminhada.
const d = $('Decidir').item.json;
let r = $json;
if (r && r.data !== undefined) {
  try { r = JSON.parse(String(r.data).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '')); } catch (e) { r = { type: 'error', message: 'resposta ilegível: ' + String(r.data).slice(0, 200) }; }
}
const ok = !(r.error || r.type === 'error');
return { json: { base: d.base, id_chamado: d.id_chamado, para: d.para, id_tecnico: d.id_tecnico, regra: d.regra,
  recebidas_antes: d.recebidas_antes, ok, resposta: r.message || r.mensagem || (r.error ? JSON.stringify(r.error) : '') } };
